head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKospiDaqTpCd = '140';
scwin.vKonexTpCd = '120';
scwin.market = $c.session.getUserInfo("market");
scwin.BTN_MAP = {"save": "btn_Save", "modify": "btn_Update"};

// var gAfStdIndCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — searchCode, setComboCode, btnShow, readSync 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {

        // 초기화함수

        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.parentRowData = $c.data.getParameter();

    grp_HDCOM_ISUR_CD.hide();
    ibx_LEADCOM_MBR_NM_STR_CD.hide(); // 코드용
    let spotIsuTrdMktTpCd = scwin.parentRowData.spotIsuTrdMktTpCd;
    if($c.util.isEmpty(spotIsuTrdMktTpCd)){
        spotIsuTrdMktTpCd = scwin.market;
    }
    if (spotIsuTrdMktTpCd === "1") {

        grp_KOSDAQ.hide();

        grp_KOSDAQ1.hide();

        grp_KSE.show();

        grp_konex_secu_list_methd_tp_cd.hide();

        lbl_leadcom.show();

        lbl_specifiedadvisor.hide();

        grp_konex_lp.hide();

        lbl_KONEX_SECT.hide();

        sbx_SPECL_LIST_TP_CD.hide();

        img_LEADCOM_MBR_NO.show();

        sbx_SKIL_GRWTH_COM_SECT_TP_CD.hide();

        lbl_acntclsMm.setValue("결산기");
    } else if (spotIsuTrdMktTpCd === "2") {

        grp_KOSDAQ.show();

        grp_KOSDAQ1.show();

        grp_KSE.hide();

        grp_konex_secu_list_methd_tp_cd.hide();

        lbl_leadcom.show();

        lbl_specifiedadvisor.hide();

        grp_konex_lp.hide();

        sbx_SPECL_LIST_TP_CD.hide();

        img_LEADCOM_MBR_NO.show();

    } else if (spotIsuTrdMktTpCd === "6") {

        grp_KOSDAQ.show();

        grp_KOSDAQ1.show();

        grp_KSE.hide();

        grp_SPAC_LAPS_MERGE_ISUR.hide();

        grp_hdcom.hide();

        grp_dirctlist.hide();

        grp_sme.hide();

        grp_peplstk.hide();

        grp_spac_yn.hide();

        grp_spac.hide();

        grp_konex_secu_list_methd_tp_cd.show();

        lbl_leadcom.hide();

        lbl_specifiedadvisor.show();

        grp_konex_lp.show();

        lbl_KONEX_SECT.show();

        sbx_SPECL_LIST_TP_CD.show();

        img_LEADCOM_MBR_NO.hide();

        sbx_SKIL_GRWTH_COM_SECT_TP_CD.hide();

    } else {
        scwin.market = '1';

        img_LEADCOM_MBR_NO.show();
    }

    if (spotIsuTrdMktTpCd === "2") {
        panel_pharma_bio_com_yn.show();
        pnl_LIST_INVSTG_COND.show();
        grp_segment.show();
    } else {
        panel_pharma_bio_com_yn.hide();
        pnl_LIST_INVSTG_COND.hide();
        grp_segment.hide();
    }
    if(spotIsuTrdMktTpCd === "1"){
        pnl_LIST_INVSTG_COND.show();
    }

    await scwin.searchCode(); // 코드1
    await scwin.setComboCode(); // 코드2

    scwin.vBzProcsNo = $c.win.getParent().scwin.clickBzProcsNo;
    if(scwin.vBzProcsNo !== "") { // 수정
        img_CoSearch.setDisabled(true);
    }  else { // 저장
        img_CoSearch.setDisabled(false);
    }

    scwin.rowPos = $c.win.getParent().dlt_newlistingRes.getRowPosition();

    // 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    await scwin.btnShow(scwin.vBzProcsNo);

    if (scwin.vBzProcsNo !== "") { // 수정
        await scwin.readSync();
        ibx_SearchCd.setValue(scwin.parentRowData.isurCd);
        ibx_SearchNm.setValue(scwin.parentRowData.comNm);
        sbx_SECUGRP_ID.setDisabled(true);
        sbx_SECUGRP_ID.setValue(scwin.parentRowData.secugrpId);
        // spac 여부에 따른 존립기간 _20100528
        if (sbx_SPAC_YN.getValue() === "Y") {

            grp_spac.show();
        }
    } else { // 신규
        grp_spac.hide();
        sbx_SECUGRP_ID.setValue($c.win.getParent().sbx_NEW_SECUGRP_ID.getValue());
        sbx_SPOT_ISU_TRD_MKT_TP_CD.setValue( scwin.market );
        $c.util.setButtonState("btnbox", "insert", scwin.BTN_MAP);
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_SPAC_LAPS_MERGE_ISUR_NM_onclick
 * @description SPAC소멸합병상장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_SPAC_LAPS_MERGE_ISUR_NM_onclick = async function() {
    try {
        // SPAC소멸합병상장의 경우만 선택  jackal_22.02.11
        if (sbx_LIST_CLSS_CD.getValue() !== "31") {
            $c.win.alert("상장구분이 [SPAC-소멸합병]의 경우만 선택하세요.");
            ibx_SPAC_LAPS_MERGE_ISUR_NM.focus();
            return false;
        }
        const res = await $c.cm.listIsurcdSearch(ibx_SPAC_LAPS_MERGE_ISUR_CD, ibx_SPAC_LAPS_MERGE_ISUR_NM, '', 'Y');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_SPAC_LAPS_MERGE_ISUR_NM_onclick" });
    }
};

/**
 * @method
 * @name img_SPAC_LAPS_MERGE_REG_DD_onclick
 * @description img_SPAC_LAPS_MERGE_REG_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SPAC_LAPS_MERGE_REG_DD_onclick = function() {
    try {
        // 스팩소멸합병등기일 jackal_22.02.11
        // SPAC소멸합병상장의 경우만 선택  jackal_22.02.11
        if (sbx_LIST_CLSS_CD.getValue() !== "31") {
            $c.win.alert("상장구분이 [SPAC-소멸합병]의 경우만 선택하세요.");
            ibx_SPAC_LAPS_MERGE_REG_DD.focus();
            return false;
        }
        popUpCalendar2(ibx_SPAC_LAPS_MERGE_REG_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05006.img_SPAC_LAPS_MERGE_REG_DD_onclick" });
    }
};

/**
 * @method
 * @name img_HDCOM_ISUR_NM_onclick
 * @description 지주회사 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_HDCOM_ISUR_NM_onclick = async function() {
    try {
        $c.cm.listIsurcdSearch(ibx_HDCOM_ISUR_CD, ibx_HDCOM_ISUR_NM, '', 'Y');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_HDCOM_ISUR_NM_onclick" });
    }
};

/**
 * @method
 * @name img_CoSearch_onclick
 * @description 법인선택 팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_CoSearch_onclick = async function() {
    try {
        if (sbx_SECUGRP_ID.getValue() === "") {
            $c.win.alert("[유가증권]을 선택하세요.");
            return;
        }
        // 이건 상세시 사용하는거 같다 scwin.getPar, scwin.setPar
        scwin.getPar = scwin.getParIsur();
        scwin.setPar = scwin.setParIsur();
        const res = await $c.lc.popFindExamCorp(sbx_SECUGRP_ID.getValue());

        if(res) {
            ibx_SearchCd.setValue(res.isurCd);
            ibx_SearchNm.setValue(res.comNm);
            if(res.isurCd !== "")  {
                scwin.companInfo(res.isurCd);

            } ;
        }

    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name btn_IsuNew_onclick
 * @description 상장종목신규111 — 「상장종목신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_IsuNew_onclick = function() {
    try {
        let isDutyDIv;
        if ((scwin.market === "1" || scwin.market === "6")
                && scwin.parentRowData.secugrpId === "ST" || scwin.parentRowData.secugrpId === "DR" || scwin.parentRowData.secugrpId === "FS") {
            isDutyDIv = true;
        } else {
            isDutyDIv = false;
        }
        $c.lc.openDetailCorpIsuProtect(0,scwin.parentRowData.secugrpId,isDutyDIv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05006.btn_IsuNew_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name sbx_SPAC_YN_onselchange
 * @description sbx_SPAC_YN 선택 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.sbx_SPAC_YN_onselchange = function() {
    try {
        // spac 여부에 따른 존립기간 _20100528
        if (sbx_SPAC_YN.getValue() === "Y") {
            // $c.stf.showObj(grp_spac, true);
            grp_spac.show();
        } else {
            // $c.stf.showObj(grp_spac, false);
            grp_spac.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05006.sbx_SPAC_YN_onselchange" });
    }
};

/**
 * @method
 * @name img_ISUR_SYMBL_onclick
 * @description 중복체크 — 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISUR_SYMBL_onclick = async function() {
    try {
        if (ibx_ISUR_SYMBL.getValue() === "") {
            $c.win.alert("[영문회사심볼]을 입력하세요.");
            ibx_ISUR_SYMBL.focus();
            return false;
        } else {
            if (await $c.lc.engSymblCheck(ibx_ISUR_SYMBL.getValue())) {
                await $c.lc.chkCorpSymblDoubleInput1(ibx_ISUR_SYMBL.getValue(), ibx_ISUR_CD.getValue());
                if (!$c.util.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
                        $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                }
            } else {
                ibx_ISUR_SYMBL.focus();
                return false;
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_ISUR_SYMBL_onclick" });
    }
};

/**
 * @method
 * @name img_LIST_NO_onclick
 * @description 상장번호 생성 — 「상장번호생성」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_LIST_NO_onclick = async function() {
    try {
        const resListNo =  await $c.lc.createListNo(scwin.market); // 시장구분코드
        ibx_LIST_NO.setValue(resListNo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_LIST_NO_onclick" });
    }
};

/**
 * @method
 * @name img_ZIPCD_onclick
 * @description 우편번호
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ZIPCD_onclick = async function() {
    try {
        scwin.setPar = scwin.setParZipCd;
        const res = await $c.lc.popFindZipCd();

        ibx_ZIPCD.setValue(res.zipNo);
        ibx_ADDR.setValue(res.addr);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_ZIPCD_onclick" });
    }
};

/**
 * @method
 * @name img_STD_IND_CD_onclick
 * @description img_STD_IND_CD 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_STD_IND_CD_onclick = async function() {
    try {
        scwin.getPar = scwin.getParStdInd()||"";
        scwin.setPar = scwin.setParStdInd()||"";
        const res = await $c.lc.popFindStdIndCd();
        if(res.stdIndCd !=="") {
        ibx_STD_IND_CD.setValue(res.stdIndCd);
        ibx_STD_IND_NM.setValue(res.indNm);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_STD_IND_CD_onclick" });
    }
};

/**
 * @method
 * @name img_LEADCOM_MBR_NO_onclick
 * @description 상장주선인팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_LEADCOM_MBR_NO_onclick =  async function() {
    try {
        // 상장주선인 정보 수정기능은 신규시만 입력토록 수정 jackal_22.02.11
        if (scwin.vBzProcsNo !== '') {
            $c.win.alert("신규로 등록할 경우에만 상장주선인 정보를 수정할수 있습니다.");
            return;
        }
        const res = await $c.lc.popFindLeadCom();
        const sText = res.map(item => item.text).join(',');
        const sValue = res.map(item => item.value);

        ibx_LEADCOM_MBR_NM_STR.setValue(sText);
        ibx_LEADCOM_MBR_NM_STR_CD.setValue(sValue);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.img_LEADCOM_MBR_NO_onclick" });
    }
};

/**
 * @method
 * @name img_LIST_DD_onclick
 * @description img_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LIST_DD_onclick = function() {
    try {
        popUpCalendar2(ica_LIST_DD);
    } catch (ex) {
