    }
};

/**
 * @method
 * @name dts_Corp_OnLoadCompleted
 * @description dts_Corp 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @returns {void}
 * @hidden N
 */
scwin.dts_Corp_OnLoadCompleted = function() {
    try {

        let vCurDate = $c.date.getServerDateTime("yyyyMMdd");
        if (scwin.vBzProcsNo === "") {
            $c.util.setButtonState("btnbox", "insert", scwin.BTN_MAP);
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            if (ica_LIST_DD.getValue() > vCurDate) {
                $c.util.setButtonState("btnbox", "update", scwin.BTN_MAP);
            } else {
                $c.util.setButtonState("btnbox", "error", scwin.BTN_MAP);
            }
        }

        if (ibx_LIST_NO.getValue() !== "") {
            // img_LIST_NO.src = "../img/btn_LstNoCrt_d.gif";
            img_LIST_NO.setDisabled(true);
        }

        // gAfStdIndCd = dts_Corp.NameValue(1, "AF_STD_IND_CD");

        if (ibx_FSS_UNQ_NO.getValue() === "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0025", ""));
        }
        /*2010.02.17 금감원 코드가 없을경유 입력할 수 이도록 해준다.
        if (getObjectValue(ibx_FSS_UNQ_NO) == "") {
            ibx_FSS_UNQ_NO.readOnly = false;
        }
         */
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05006.dts_Corp_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description trs_Save 트랜잭션 실패 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        scwin.alertJobMsg('F');
        $c.win.alert(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05006.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description trs_Save 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        scwin.alertJobMsg('S');
        scwin.parentRefresh();

        // 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
        scwin.btnShow(scwin.vBzProcsNo);
        if (buttonSet.status === "U") {
            const parentWin = $c.win.getParent();
            parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
        }
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            if (scwin.market === "2") {
                // 저장시 소속부변경 알림 팝업
                $c.win.alert("소속부변경_STF05234 화면에서 확인하여 주십시오");
            }
            await $c.win.closePopup();
        } else {
            scwin.readSync(); // 상세조회
            if (scwin.market === "2") {
                // 저장시 소속부변경 알림 팝업
                $c.win.alert("소속부변경_STF05234 화면에서 확인하여 주십시오");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05006.trs_Save_OnSuccess" });
    }
};

