/**
 * @method
 * @name companInfo
 * @description 신규상장할 예비심사 회사 정보 개별검색(회사코드이용)
 * @param {String} isurCd 코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.companInfo = async function(isurCd) {

    const param = {"isurCd": isurCd};
    const sbmOptions = {
        id : "sbm_companyInfo",
        action : "/api/listing/lstproc/stock/newlisting/select-corpinfo-byisurcd",
        method : "get",
        target : "dma_companyInfoRes=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions, param);
    let values = res.responseJSON.body;sbx_MAINTR_BK_CD
    if(res.responseJSON.success) {
        ibx_ISUR_CD.setValue(values.isurCd);
        ibx_COM_NM.setValue(values.comNm);
        ibx_FSS_UNQ_NO.setValue(values.fssUnqNo);
        ibx_CEO_NM.setValue(values.ceoNm);
        ibx_COM_ABBRV.setValue(values.comAbbrv);
        ibx_CORP_REG_NO.setValue(values.corpRegNo)
        ibx_BZ_REG_NO.setValue(values.bzRegNo);
        if(values.oldListDd !== null) ica_LIST_DD.setValue(values.oldListDd);
        ica_FOUND_DD.setValue(values.foundDd);
        ibx_ISUR_SYMBL.setValue(values.isurSymbl);
        ibx_COM_ENG_NM.setValue(values.comEngNm);
        txb_MAJ_PROD_NM.setValue(values.majProdNm);
        ibx_HPAGE.setValue(values.hpage);
        ibx_CORP_TEL_NO.setValue(values.corpTelNo);
        ibx_DTL_ADDR.setValue(values.dtlAddr);
        ibx_HEADQTR_FAX_NO.setValue(values.headqtrFaxNo);
        sbx_EXT_AUDTR_CD.setValue(values.extAudtrCd);
        // ibx_STD_IND_NM.setValue(values.stdIndCd);
        ibx_STD_IND_CD.setValue(values.stdIndCd);
        ibx_ZIPCD.setValue(values.zipcd);
        ibx_ADDR.setValue(values.addr);
        ibx_DTL_ADDR.setValue(values.dtlAddr) // 나머지주소

        sbx_MAINTR_BK_CD.setValue(values.maintrBkCd) // 주거래은행

    }
}

