/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';

    if (await scwin.checkForm()) {
        if (!await($c.lc.isProcess(scwin.TR_JOB))) return; // 메시지처리
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();// TO-BE: api를 새로 만들어줌
        // $c.win.alert("[bz_procs_no]"+bz_procs_no);
        if (String(scwin.vBzProcsNo).length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dma_newListingComInfoRes.set("bzProcsNo", scwin.vBzProcsNo)
            await scwin.trs(scwin.TR_JOB);
        }
    }
};

