        }
    }
};

/**
 * @method
 * @name checkBiz
 * @description 사업자등록번호 입력값을 확인한다.
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.checkBiz = function() {
    if (dts_Isu.getRowCount() === 0) {
        $c.win.alert("[상장종목]을 입력하세요.");
        return false;
    }
    if (scwin.market === "6" && dts_konex.getRowCount() === 0) {
        $c.win.alert("[코넥스증권발행내역]을 입력하세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name dscl
 * @description 공시 안내문 작성 화면을 연다.
 * @returns {Promise<*>} 결과 값
 * @hidden N
 */
scwin.dscl = async function() {
    if ($c.cp.isModified(dts_Corp)) {
        $c.win.alert("수정된 내용이 있으니, 수정후  안내문 작성 버튼을 눌러주세요.");
        return;
    }
    if (!scwin.checkBiz()) {
        return;
    }

    // 미 완료 업무 체크
    let param = '';
    let msg = '';
    let Mkt_Id = dts_Corp.getCellData(dts_Corp.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD");
    param += "&{P}V_BZ_PROCS_NO=" + scwin.vBzProcsNo;
    if (Mkt_Id === "6") // 코넥이면
        param += "&{P}V_LIST_INVSTG_BZ_TP_CD=" + scwin.vKonexTpCd;

    else param += "&{P}V_LIST_INVSTG_BZ_TP_CD=" + scwin.vKospiDaqTpCd;
    const dsNm = 'CODE_OUT_DEP_CD';
    const qryId = 'lds.stf.stinvstg.newlist.select.infodoc.acptcompltyn.check';
    $c.bns.searchBns("ULDSTF05006.xml", dts_InfoDoc, dsNm, qryId, param);
    const chk1 = dts_InfoDoc.getCellData(1, 'VALUE');
    const chk2 = dts_InfoDoc.getCellData(1, 'TEXT');
    if (chk1 === 'N') {
        msg = '현재 다음 항목에 대해서 주관사가 수정중입니다. \n\n [' + chk2 + ']\n\n안내문 계속 작성 하시겠습니까?';
        if (!window.confirm(msg)) return;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        let Mkt_Id = dts_Corp.getCellData(dts_Corp.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD");
        const List_Clss_Id = sbx_LIST_CLSS_CD.getValue();
        if (Mkt_Id === "1") {
            if (List_Clss_Id === '31') // 31 SPAC-소멸합병 jackal_22.02.11

            {
                arr[0] = "68158"; // SPAC-소멸합병 신규상장

            } else if (List_Clss_Id === '10') {
                arr[0] = "68152A"; // 신규상장

            } else {
                arr[0] = "68156"; // 재상장

            }
            // TODO Stage2: 외부 공통 $c.pre_newlisting 미반입 — 대응 함수 확인
            arr[5] = $c.pre_newlisting.fn_getDsclsTitle(ibx_COM_NM.getValue(), ica_LIST_DD.getValue());
            // TODO Stage2: 외부 공통 $c.pre_newlisting 미반입 — 대응 함수 확인
            $c.pre_newlisting.fn_read_sync_corpisu_discls(dts_Discls_Isu, ibx_ISUR_CD.getValue(), ica_LIST_DD.getValue());
            $c.stf.copyDataSet(dts_Discls_Isu, param_dts_isu);
        } else if (Mkt_Id === "2") {
            if (List_Clss_Id === '31') // 31 SPAC-소멸합병 jackal_22.02.11

            {
                arr[0] = "70980";
            } else if (List_Clss_Id === '10') // 신규상장

            {
                arr[0] = "70760";
            } else {
                arr[0] = "70779"; // 재상장

            }
            $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        } else if (Mkt_Id === "6") {
            if (List_Clss_Id === '10') {
                // 신규상장일 경우
                if (dts_konex.getCellData(1, "KONEX_SECU_ISU_YN") === "Y") {
                    arr[0] = "32001";
                    $c.stf.copyDataSet(dts_konex, param_dts2);
                } else {
                    arr[0] = "32002";
                }
            }
            /*else  { 재상장인데 매매거래정지 안내문이 나옴. 코넥스 재상장 서식 정의가 안 되어 있음 2015.06
                    arr[0] = "32012";
                }   */

            $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        }
        let dBzProcsNo = scwin.vBzProcsNo;
        for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo === "" ? "" : ",") + dts_Isu.getCellData(i, "BZ_PROCS_NO");
        }
        arr[1] = dBzProcsNo;
        // arr[1] = dts_Corp.NameValue(1, "BZ_PROCS_NO") ;
        arr[2] = dts_Corp.getCellData(1, "ISUR_CD");
        arr[3] = Mkt_Id;
        $c.stf.copyDataSet(dts_Corp, param_dts_mst);
        for (i = 1; i <= param_dts_isu.getRowCount(); i++) {
            if (param_dts_isu.getCellData(i, "STKCERT_KIND_CD") === "000") {
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DIV_RECK_DD1", param_dts_isu.getCellData(i, "DIV_RECK_DD1"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_PRC", param_dts_isu.getCellData(i, "ISU_PRC"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CD", param_dts_isu.getCellData(i, "ISU_CD"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_SRT_CD", param_dts_isu.getCellData(i, "ISU_SRT_CD"));
                param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_DD", param_dts_isu.getCellData(i, "ISU_DD"));
            }
        }
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "LIST_CLSS_NM", sbx_LIST_CLSS_CD.getText());
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "SEG_TP_NM", sbx_SEG_TP_CD.getText());
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    // TODO Stage2: 레거시 모달 좌표 계산 — openPopup 은 위치 옵션으로 대체
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

