/**
 * @method
 * @name btnShow
 * @description 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
 * @param {String|Number} val 값
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btnShow = async function(val) {

    if (val !== "") {
        // 업무처리번호가 있음.
        btn_IsuNew.setDisabled(false);
        lab_btn.hide();
        if (scwin.market === "6") {
            // $c.stf.showObj(btn_secu, true);
            btn_secu.show();
        } else {
            // $c.stf.showObj(btn_secu, false);
            btn_secu.hide();
        }
    } else {
        btn_IsuNew.setDisabled(true);
        lab_btn.show();
        btn_secu.hide();
    }
};

